public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    int start = 0;
    while (start < path.length()) {
        int end = path.indexOf('/', start);
        if (end == -1) {
            pathSegments.add(new PathSegmentImpl(path.substring(start)));
            break;
        }
        if (end > start && decode) {
            pathSegments.add(new PathSegmentImpl(decodeURIComponent(path.substring(start, end))));
        } else {
            pathSegments.add(new PathSegmentImpl(path.substring(start, end)));
        }
        start = end + 1;
    }
    return pathSegments;
}
