private void pop(final String descriptor) throws IndexExtractionException, IllegalStateException {
    if (Strings.isNullOrEmpty(descriptor)) {
        // Log null descriptor
        return;
    }

    if (descriptor.startsWith("(") && descriptor.endsWith(")")) {
        // Descriptor is a method signature
        // Extract the param names from the method signature
        String[] paramNames = Strings.squeeze(descriptor.substring(1, descriptor.length() - 1), "(").split(",");
        for (String paramName : paramNames) {
            this.popType(paramName);
        }
        this.skipWhitespace();
    } else if (descriptor.startsWith("[") && descriptor.endsWith("]")) {
        // Descriptor is an array
        this.popArray(descriptor);
    } else {
        // Descriptor represents a single type
        this.popType(descriptor);
        this.skipWhitespace();
    }
}
