    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i == len - 1) {
                throw new Exception("Invalid escape sequence");
            }
            ch = str.charAt(i + 1);
            if (ch == '\\') { // escaped \\\
                sb.append(ch);
                i++;
            } else if (ch == 'n') { // escaped newline
                sb.append('\n');
            } else if (ch == 't') { // escaped tab
                sb.append('\t');
            } else if (ch == 'r') { // escaped carriage return
                sb.append('\r');
            } else if (ch == 'b') { // escaped backspace
                sb.append('\b');
            } else if (ch == 'f') { // escaped form feed
                sb.append('\f');
            } else if (ch == '0') { // escaped null character
                sb.append('\0');
            } else if (ch == 'x' && len >= i + 3) { // escaped hex character
                char hex1 = str.charAt(i + 2);
                char hex2 = str.charAt(i + 3);
                int value = Integer.parseInt("" + hex1 + hex2, 16);
                sb.append((char) value);
                i += 3;
            } else if (ch == 'u' && len >= i + 6) { // escaped unicode character
                char utf16 = str.charAt(i + 2);
                char utf161 = str.charAt(i + 3);
                char utf162 = str.charAt(i + 4);
                char utf163 = str.charAt(i + 5);
                String unicodeString = "" + utf16 + utf161 + utf162 + utf163;
                sb.append(unescapeUnicode(unicodeString));
                i += 6;
            } else if (ch == 'z') { // escaped zero-length string
                sb.append(""); // Note: This is different from unescaping in Unicode, which means an empty string.
            } else {
                throw new Exception("Unsupported escape sequence");
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

