private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new ArrayList<>();
    // Sort the keys in descending order to easily apply lower bound computation
    Collections.sort(keys, Collections.reverseOrder());
    int minUpperBound = Integer.MAX_VALUE;
    for (K key : keys) {
        if (key.compareTo(minUpperBound) > 0 && key.compareTo(Integer.MIN_VALUE) < 0) {
            // Update the minimum upper bound
            minUpperBound = key;
        }
        upperBounds.add(minUpperBound);
    }
    return upperBounds;
}
